(() => {
  loadLevel(0);
  if (snapToGridEnabled) toggleSnapToGrid();
  const board = document.getElementById('gameCanvas');
  const rect = board.getBoundingClientRect();
  // Level 1 turns a horizontal ray upward: the target's x meets the source's y.
  const x = gameState.target.x;
  const y = gameState.laserSource.y;
  const pointer = new MouseEvent('dblclick', { bubbles: true, clientX: rect.left + x, clientY: rect.top + y });
  board.dispatchEvent(pointer);
  const mirror = gameState.mirrors[0];
  if (!mirror || gameState.mirrors.length !== 1) throw new Error('Level 1 mirror was not placed');
  // MouseEvent may round fractional CSS pixels; physics and drawing must use that same point.
  if (Math.abs(mirror.x - x) > 1 || Math.abs(mirror.y - y) > 1) throw new Error('Mirror missed the source/target intersection');
  if (Math.abs(mirror.x - (pointer.clientX - rect.left)) > 1e-6 || Math.abs(mirror.y - (pointer.clientY - rect.top)) > 1e-6) throw new Error('Pointer and logical mirror coordinates disagree');
  const edge = mirror.getEndpoints();
  if (Math.abs((edge.x1 + edge.x2) / 2 - mirror.x) > 1e-6 || Math.abs((edge.y1 + edge.y2) / 2 - mirror.y) > 1e-6) throw new Error('Drawn mirror endpoints disagree with its logical center');
  fireLaser();
  closeControlsPanelOnMobile();
})()

(async () => {
  const deadline = performance.now() + 8000;
  await new Promise((resolve, reject) => {
    const check = () => {
      if (gameState.won && gameState.target.hit && !laserAnimating && (laserAnimDone || prefersReducedMotion)) return resolve();
      if (performance.now() > deadline) return reject(new Error('Level 1 did not finish a winning beam trace'));
      requestAnimationFrame(check);
    };
    check();
  });
})()
